import{_ as i,o as t,c as l,a2 as a}from"./chunks/framework.DpXDHk3d.js";const q=JSON.parse('{"title":"14.2 仪表使用实操要点","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/14-chapter-14-shi-cao-kao-he-yu-ying-shi-ji-qiao/14-2-yi-biao-shi-yong-shi-cao-yao-dian.md","filePath":"electrician/low-voltage-electrician/14-chapter-14-shi-cao-kao-he-yu-ying-shi-ji-qiao/14-2-yi-biao-shi-yong-shi-cao-yao-dian.md","lastUpdated":1793096070000}'),r={name:"electrician/low-voltage-electrician/14-chapter-14-shi-cao-kao-he-yu-ying-shi-ji-qiao/14-2-yi-biao-shi-yong-shi-cao-yao-dian.md"};function n(s,o,e,g,h,u){return t(),l("div",null,[...o[0]||(o[0]=[a('<h1 id="_14-2-仪表使用实操要点" tabindex="-1">14.2 仪表使用实操要点 <a class="header-anchor" href="#_14-2-仪表使用实操要点" aria-label="Permalink to &quot;14.2 仪表使用实操要点&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>万用表、钳形表、兆欧表是实操考核&quot;必上手的家伙&quot;。这一节梳理三块表的使用步骤和注意事项,按考官眼里&quot;规范动作&quot;来做。</p><h2 id="一、万用表的使用-测电压、电阻" tabindex="-1">一、万用表的使用(测电压、电阻) <a class="header-anchor" href="#一、万用表的使用-测电压、电阻" aria-label="Permalink to &quot;一、万用表的使用(测电压、电阻)&quot;">​</a></h2><p><strong>基本步骤</strong>:</p><ol><li><strong>选择挡位</strong>:先选挡位再测量——测交流电压选&quot;交流电压&quot;挡(V~),测电阻选&quot;Ω&quot;挡;</li><li><strong>选量程</strong>:量程从大到小,读数约满量程的 1/3~2/3 最准;无法估计时从最大量程试起;</li><li><strong>接表笔</strong>:红表笔接&quot;+&quot;(V/Ω)孔,黑表笔接&quot;COM&quot;孔;</li><li><strong>测量电压</strong>:表笔并联在被测电路两端(测电压要并联);</li><li><strong>测电阻</strong>:先<strong>断电、断开电路</strong>,表笔并接在电阻两端(测电阻不能带电);</li><li><strong>读数和收尾</strong>:正确读刻度(注意倍率),用后拨回&quot;OFF&quot;挡或交流电压最高挡。</li></ol><p><strong>安全要点</strong>:</p><ul><li>测电压时表笔并联;测电阻前<strong>先断电</strong>;</li><li>量程拨错(如用电阻挡测电压)会烧表——<strong>先选挡、再测量</strong>;</li><li>不能带电测电阻。</li></ul><blockquote><p>⚠️ 判断题/实操扣分点:<strong>万用表测电压要并联,测电阻要断电、先选挡</strong>;换挡前表笔离开被测点。</p></blockquote><h2 id="二、钳形电流表的使用-测电流" tabindex="-1">二、钳形电流表的使用(测电流) <a class="header-anchor" href="#二、钳形电流表的使用-测电流" aria-label="Permalink to &quot;二、钳形电流表的使用(测电流)&quot;">​</a></h2><p><strong>基本步骤</strong>:</p><ol><li>选择挡位和量程(交流电流挡);</li><li>把被测导线<strong>卡入钳口</strong>(卡<strong>一根</strong>导线);</li><li>读取电流值;小电流可把导线在钳口多绕几圈,读数除以圈数;</li></ol><p><strong>安全要点</strong>:</p><ul><li><strong>钳形表测电流不用断开电路</strong>,卡住导线即可;</li><li>必须卡<strong>单根导线</strong>,同时卡住火线和零线读数为 0(两线电流抵消);</li><li>测高压/带电导线时注意安全距离和绝缘;</li><li>量程先大后小,避免损坏。</li></ul><blockquote><p>⚠️ 实操扣分点:<strong>钳形表同时卡两根线会测不出电流</strong>;测量时钳口要闭合好。</p></blockquote><h2 id="三、兆欧表的使用-测绝缘电阻" tabindex="-1">三、兆欧表的使用(测绝缘电阻) <a class="header-anchor" href="#三、兆欧表的使用-测绝缘电阻" aria-label="Permalink to &quot;三、兆欧表的使用(测绝缘电阻)&quot;">​</a></h2><p><strong>基本步骤</strong>:</p><ol><li>测量前<strong>断电</strong>,并确认设备无电、放电;</li><li>检查表本身:开路摇测(L、E 悬空)指针应在&quot;∞&quot;,短路摇测指针应在&quot;0&quot;(校验);</li><li>接线:<strong>L 端</strong>接被测绕组/导线,<strong>E 端</strong>接设备外壳(地);</li><li>摇动手柄至额定转速(约 120 r/min),待指针稳定后读数;</li><li>测电容性设备后<strong>先放电</strong>,再拆线。</li></ol><p><strong>安全要点</strong>:</p><ul><li>兆欧表<strong>产生高电压</strong>(500V/1000V),<strong>严禁带电测量</strong>,测前必须断电;</li><li>被测设备要放电(尤其电容器、电缆);</li><li>测量时人不能同时触碰被测导体和地。</li></ul><blockquote><p>⚠️ 判断题高频:<strong>兆欧表测绝缘必须在断电状态下进行</strong>;测量对象是&quot;绝缘电阻&quot;,单位兆欧(MΩ)。</p></blockquote><h2 id="四、考点提示" tabindex="-1">四、考点提示 <a class="header-anchor" href="#四、考点提示" aria-label="Permalink to &quot;四、考点提示&quot;">​</a></h2><ul><li>✅ 万用表:测电压并联、测电阻先断电、先选挡。</li><li>✅ 钳形表:不拆线测电流,卡<strong>单根</strong>导线。</li><li>✅ 兆欧表:测绝缘,必须<strong>断电</strong>测量,摇测读数。</li><li>⚠️ 易混点:钳形表(电流)、万用表(电压/电阻)、兆欧表(绝缘)——三表测什么别搞混。</li></ul><h2 id="五、本节小结" tabindex="-1">五、本节小结 <a class="header-anchor" href="#五、本节小结" aria-label="Permalink to &quot;五、本节小结&quot;">​</a></h2><ul><li>万用表规范:选挡→并联/断电→读数→收尾。</li><li>钳形表:卡单根导线、不断电测电流。</li><li>兆欧表:断电、放电、摇测绝缘。</li></ul><h2 id="六、自测练习" tabindex="-1">六、自测练习 <a class="header-anchor" href="#六、自测练习" aria-label="Permalink to &quot;六、自测练习&quot;">​</a></h2><ol><li>(判断)用万用表测电阻时,应在通电状态下测量。( )</li><li>(单选)测量交流电路中的电流,且不需断开电路,应使用()。 A. 万用表　B. 钳形电流表　C. 兆欧表　D. 电能表</li><li>(判断)钳形电流表同时卡住火线和零线,读数不为零。( )</li><li>(单选)用兆欧表测量绝缘电阻前,必须()。 A. 带电测量　B. 先断开电源并放电　C. 加大量程　D. 并联被测设备</li><li>(判断)兆欧表摇动手柄至额定转速,指针稳定后读数。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>×</strong>。测电阻必须断电,带电测会损坏并测不准。</li><li><strong>B</strong>。钳形表可不断开电路测电流。</li><li><strong>×</strong>。同时卡两线,两电流抵消,读数为零。</li><li><strong>B</strong>。兆欧表测量前必须断电并放电。</li><li><strong>√</strong>。摇到额定转速、指针稳定后读数。</li></ol></details>',28)])])}const d=i(r,[["render",n]]);export{q as __pageData,d as default};
